const requestMediaPermissions = async (video = true) => {
  let stream;
  let error;
  try {
    stream = await navigator.mediaDevices.getUserMedia({
      audio: true,
      video
    });
  } catch (err) {
    // user likely doesn't have a webcam,
    // we should still allow to select a microphone
    if (video && err.name === "NotFoundError") {
      try {
        stream = await navigator.mediaDevices.getUserMedia({
          audio: true
        });
      } catch (err) {
        error = err;
      }
    } else {
      error = err;
    }
  }
  if (error) {
    logger/* logger */.vF.log("Failed to list userMedia devices", error);
    const brand = SdkConfig/* default */.A.get().brand;
    Modal/* default */.Ay.createDialog(ErrorDialog/* default */.A, {
      title: (0,languageHandler._t)("voip|no_media_perms_title"),
      description: (0,languageHandler._t)("voip|no_media_perms_description", {
        brand
      })
    });
  }
  return stream;
};
